import { z } from "zod";
import { PROTOCOL_VERSION, SCENE_LIMITS, type SceneDocument } from "./contracts";

const rect = z.object({ x: z.number().finite(), y: z.number().finite(), width: z.number().nonnegative().finite(), height: z.number().nonnegative().finite() });
const node = z.object({
  id: z.string().min(1),
  parentId: z.string().optional(),
  children: z.array(z.string()),
  kind: z.enum(["container", "box", "text", "image", "svg", "fallback"]),
  name: z.string().max(200),
  source: z.string().max(2_000),
  rect,
  zIndex: z.number().finite(),
  paint: z.record(z.string(), z.unknown()),
  layout: z.record(z.string(), z.unknown()),
  text: z.string().max(100_000).optional(),
  textStyle: z.record(z.string(), z.unknown()).optional(),
  assetId: z.string().optional(),
  fallbackReason: z.string().max(1_000).optional()
});

const sceneSchema = z.object({
  protocolVersion: z.literal(PROTOCOL_VERSION),
  viewport: z.object({ id: z.string(), name: z.string(), width: z.number().positive(), height: z.number().positive() }),
  documentSize: z.object({ width: z.number().positive(), height: z.number().positive() }),
  nodes: z.array(node).max(SCENE_LIMITS.maxLayers),
  assets: z.array(z.record(z.string(), z.unknown())).max(SCENE_LIMITS.maxLayers),
  diagnostics: z.array(z.record(z.string(), z.unknown())).max(SCENE_LIMITS.maxLayers)
});

export function validateScenes(value: unknown): SceneDocument[] {
  const scenes = z.array(sceneSchema).min(1).parse(value) as unknown as SceneDocument[];
  const bytes = new TextEncoder().encode(JSON.stringify(scenes)).byteLength;
  if (bytes > SCENE_LIMITS.maxMessageBytes) throw new Error("Import is larger than the 25 MB safety limit.");
  for (const scene of scenes) {
    if (scene.documentSize.height > SCENE_LIMITS.maxHeight) {
      throw new Error(`${scene.viewport.name} exceeds the 100,000px height limit.`);
    }
  }
  return scenes;
}

export function sceneWarnings(scenes: SceneDocument[]) {
  const layers = scenes.reduce((total, scene) => total + scene.nodes.length, 0);
  const tall = scenes.filter((scene) => scene.documentSize.height > SCENE_LIMITS.warningHeight);
  return {
    layers,
    needsLayerConfirmation: layers > SCENE_LIMITS.warningLayers,
    tallViewports: tall.map((scene) => scene.viewport.name)
  };
