import { describe, expect, it } from "vitest";
import { isSafeBaseUrl, prepareSandboxDocument } from "./prepareDocument";
import type { ViewportSpec } from "../shared/contracts";

const viewport: ViewportSpec = { id: "desktop", name: "Desktop", width: 1440, height: 900 };

describe("sandbox document preparation", () => {
  it("accepts only web base URLs", () => {
    expect(isSafeBaseUrl("https://example.com/assets/")).toBe(true);
    expect(isSafeBaseUrl("javascript:alert(1)")).toBe(false);
    expect(isSafeBaseUrl("file:///tmp/page")).toBe(false);
  });

  it("removes supplied scripts when scripts are disabled", () => {
    const result = prepareSandboxDocument({ html: "<script>window.bad = true</script><main>Hello</main>", baseUrl: "https://example.com/", scriptPolicy: "off", token: "test", viewport, settleDelayMs: 0 });
    expect(result).not.toContain("window.bad");
    expect(result).toContain("Content-Security-Policy");
    expect(result).toContain("<base href=\"https://example.com/\">");
  });

  it("keeps trusted scripts but gives them a nonce", () => {
    const result = prepareSandboxDocument({ html: "<script src=\"app.js\"></script>", scriptPolicy: "trusted", token: "test", viewport, settleDelayMs: 0 });
    expect(result).toContain("src=\"app.js\" nonce=");
    expect(result).toContain("connect-src http: https:");
  });
});

import { describe, expect, it } from "vitest";
import { PROTOCOL_VERSION, type SceneDocument } from "./contracts";
import { sceneWarnings, validateScenes } from "./validation";

function scene(overrides: Partial<SceneDocument> = {}): SceneDocument {
  return {
    protocolVersion: PROTOCOL_VERSION,
    viewport: { id: "desktop", name: "Desktop", width: 1440, height: 900 },
    documentSize: { width: 1440, height: 900 },
    nodes: [{ id: "root", children: [], kind: "container", name: "body", source: "body", rect: { x: 0, y: 0, width: 1440, height: 900 }, zIndex: 1, paint: {}, layout: { kind: "none" } }],
    assets: [],
    diagnostics: [],
    ...overrides
  };
}

describe("scene validation", () => {
  it("accepts a protocol-compatible scene", () => {
    expect(validateScenes([scene()])).toHaveLength(1);
  });

  it("rejects impossible document height", () => {
    expect(() => validateScenes([scene({ documentSize: { width: 1440, height: 100_001 } })])).toThrow("100,000px");
  });

  it("reports confirmation thresholds", () => {
    const manyNodes = Array.from({ length: 5_001 }, (_, index) => ({ id: `n-${index}`, children: [], kind: "box" as const, name: "box", source: "div", rect: { x: 0, y: 0, width: 1, height: 1 }, zIndex: index, paint: {}, layout: { kind: "none" as const } }));
    const warnings = sceneWarnings([scene({ nodes: manyNodes, documentSize: { width: 1440, height: 30_001 } })]);
    expect(warnings.needsLayerConfirmation).toBe(true);
    expect(warnings.tallViewports).toEqual(["Desktop"]);
  });
});

import { describe, expect, it } from "vitest";
import { buildExtractorScript } from "./extractor";

describe("extractor script", () => {
  it("embeds the viewport, token, and protocol result", () => {
    const script = buildExtractorScript("nonce-token", { id: "mobile", name: "Mobile", width: 390, height: 844 }, 1200);
    expect(script).toContain("nonce-token");
    expect(script).toContain('"width":390');
    expect(script).toContain("CAPTURE_RESULT");
    expect(script).toContain("UNSUPPORTED_SUBTREE");
  });
});

