      const message = event.data;
      if (!message || typeof message !== "object" || !("type" in message)) return;
      if (message.type === "PROGRESS") setProgress(`${message.label}: ${message.completed}/${message.total}`);
      if (message.type === "COMPLETE") {
        setPhase("complete");
        setProgress(`Imported ${message.boards} editable board${message.boards === 1 ? "" : "s"}.`);
      }
      if (message.type === "ERROR") {
        setPhase("error");
        setError(message.message);
      }
    };
    window.addEventListener("message", receive);
    return () => window.removeEventListener("message", receive);
  }, []);

  const warnings = useMemo(() => sceneWarnings(scenes), [scenes]);
  const diagnostics = useMemo(() => scenes.flatMap((scene) => scene.diagnostics), [scenes]);
  const resetCapture = () => {
    setScenes([]);
    if (phase !== "importing") setPhase("idle");
  };

  const analyze = async () => {
    if (!source.trim()) {
      setPhase("error");
      setError("Paste the HTML for one page before analyzing it.");
      return;
    }
    if (baseUrl && !isSafeBaseUrl(baseUrl)) {
      setPhase("error");
      setError("The base URL must use http:// or https://.");
      return;
    }
    if (scriptPolicy === "trusted" && !window.confirm("Only enable scripts for source you trust. A sandbox prevents access to Penpot, but a broken or hostile script can still hang this plugin tab. Continue?")) return;
    setError(undefined);
    setScenes([]);
    setPhase("capturing");
    setProgress("Rendering Desktop…");
    try {
      const request: CaptureRequest = { protocolVersion: PROTOCOL_VERSION, html: source, baseUrl: baseUrl || undefined, viewports, scriptPolicy, settleDelayMs };
      const captured = await capturePage(request, (completed, total) => setProgress(`Rendered ${completed}/${total} viewport${total === 1 ? "" : "s"}.`));
      setScenes(captured);
      setPhase("ready");
      setProgress(`Analyzed ${captured.length} viewport${captured.length === 1 ? "" : "s"}.`);
    } catch (captureError) {
      setPhase("error");
      setError(captureError instanceof Error ? captureError.message : "Unable to render the supplied page.");
    }
  };

  const importScenes = () => {
    if (!scenes.length) return;
    if ((warnings.needsLayerConfirmation || warnings.tallViewports.length) && !window.confirm(`This import contains ${warnings.layers.toLocaleString()} layers${warnings.tallViewports.length ? ` and tall boards (${warnings.tallViewports.join(", ")})` : ""}. It may be slow. Import anyway?`)) return;
    setPhase("importing");
    setError(undefined);
    setProgress("Preparing Penpot layers…");
    postToPlugin({ type: "IMPORT", protocolVersion: PROTOCOL_VERSION, scenes });
  };

  const cancel = () => {
    postToPlugin({ type: "CANCEL", protocolVersion: PROTOCOL_VERSION });
    setProgress("Cancelling after the current layer…");
  };

  const updateViewport = (id: string, field: keyof ViewportSpec, value: string) => {
    setViewports((current) => current.map((viewport) => viewport.id !== id ? viewport : field === "name" || field === "id" ? { ...viewport, [field]: value } : { ...viewport, [field]: Math.max(1, Number(value) || 1) }));
    resetCapture();
  };

  return <main className="app-shell">
    <header>
      <div>
        <h1>Ultimate HTML to Penpot</h1>
        <p>Turn one rendered HTML page into editable boards.</p>
      </div>
      <span className={`status status-${phase}`}>{phase === "ready" ? "Ready" : phase === "importing" ? "Importing" : phase === "capturing" ? "Analyzing" : phase === "complete" ? "Done" : "Draft"}</span>
    </header>

    <section className="source-section" aria-label="Page source">
      <label htmlFor="base-url">Base URL <span>optional — resolves relative assets</span></label>
      <input id="base-url" value={baseUrl} placeholder="https://example.com/page/" onChange={(event) => { setBaseUrl(event.target.value); resetCapture(); }} />
      <textarea className="editor" value={source} spellCheck={false} aria-label="HTML source" onChange={(event) => { setSource(event.target.value); resetCapture(); }} />
    </section>

    <section className="viewport-section">
      <div className="section-heading"><h2>Responsive boards</h2><button className="text-button" onClick={() => { setViewports([...viewports, { id: crypto.randomUUID(), name: "Custom", width: 1024, height: 800 }]); resetCapture(); }}>Add viewport</button></div>
      <div className="viewport-list">
        {viewports.map((viewport) => <div className="viewport-row" key={viewport.id}>
          <input aria-label={`${viewport.name} name`} value={viewport.name} onChange={(event) => updateViewport(viewport.id, "name", event.target.value)} />
          <input aria-label={`${viewport.name} width`} type="number" min="1" value={viewport.width} onChange={(event) => updateViewport(viewport.id, "width", event.target.value)} />
          <span>×</span>
          <input aria-label={`${viewport.name} height`} type="number" min="1" value={viewport.height} onChange={(event) => updateViewport(viewport.id, "height", event.target.value)} />
          <button aria-label={`Remove ${viewport.name}`} className="icon-button" disabled={viewports.length === 1} onClick={() => { setViewports(viewports.filter((item) => item.id !== viewport.id)); resetCapture(); }}>×</button>
        </div>)}
      </div>
    </section>

    <section className="advanced-section">
      <button className="advanced-toggle" onClick={() => setAdvanced(!advanced)} aria-expanded={advanced}>Advanced capture {advanced ? "−" : "+"}</button>
      {advanced && <div className="advanced-panel">
        <label className="checkbox"><input type="checkbox" checked={scriptPolicy === "trusted"} onChange={(event) => { setScriptPolicy(event.target.checked ? "trusted" : "off"); resetCapture(); }} /> Run trusted page scripts <span>Off by default. Never use for untrusted HTML.</span></label>
        <label>Additional settle delay <output>{settleDelayMs}ms</output><input type="range" min="0" max="5000" step="100" value={settleDelayMs} onChange={(event) => { setSettleDelayMs(Number(event.target.value)); resetCapture(); }} /></label>
      </div>}
    </section>

    {scenes.length > 0 && <section className="analysis" aria-live="polite">
      <h2>Analysis</h2>
      <div className="summary"><strong>{warnings.layers.toLocaleString()}</strong> editable layers across {scenes.length} boards · {diagnostics.length} diagnostics</div>
      <ul>
        {scenes.map((scene) => <li key={scene.viewport.id}>{viewportLabel(scene.viewport)} — {scene.documentSize.width}×{Math.round(scene.documentSize.height)}px, {scene.nodes.length} layers</li>)}
        {diagnostics.slice(0, 4).map((diagnostic, index) => <li className="warning" key={`${diagnostic.code}-${index}`}>{diagnostic.message} {diagnostic.source ? `(${diagnostic.source})` : ""}</li>)}
        {diagnostics.length > 4 && <li className="warning">+ {diagnostics.length - 4} more diagnostics</li>}
      </ul>
    </section>}

    {error && <p className="error" role="alert">{error}</p>}
    {(phase === "capturing" || phase === "importing" || phase === "complete" || phase === "ready") && <p className="progress" aria-live="polite">{progress}</p>}
    <footer>
      {phase === "importing" ? <button className="secondary" onClick={cancel}>Cancel import</button> : <button className="secondary" onClick={analyze} disabled={phase === "capturing"}>Analyze page</button>}
      <button className="primary" onClick={importScenes} disabled={phase !== "ready"}>Import to Penpot</button>
    </footer>
  </main>;
}

import { PROTOCOL_VERSION, type ViewportSpec } from "../shared/contracts";

/** A self-contained script run inside the opaque, sandboxed document. */
export function buildExtractorScript(token: string, viewport: ViewportSpec, settleDelayMs: number): string {
  const encodedViewport = JSON.stringify(viewport);
  return `
(() => {
  const token = ${JSON.stringify(token)};
  const viewport = ${encodedViewport};
  const delay = ${Math.max(0, Math.min(settleDelayMs, 10_000))};
  const diagnostics = [];
  const assets = new Map();
  const nodes = [];
  let sequence = 0;

  const number = (value) => { const parsed = parseFloat(value || "0"); return Number.isFinite(parsed) ? parsed : 0; };
  const compact = (value) => String(value || "").replace(/\\s+/g, " ").trim();
  const rectOf = (rect) => ({ x: Math.round(rect.x * 100) / 100, y: Math.round(rect.y * 100) / 100, width: Math.round(rect.width * 100) / 100, height: Math.round(rect.height * 100) / 100 });
  const visible = (element, style, rect) => style.display !== "none" && style.visibility !== "hidden" && number(style.opacity) !== 0 && (rect.width > 0 || rect.height > 0);
  const sourceOf = (element) => {
    if (element.id) return "#" + CSS.escape(element.id);
    const parts = [];
    let cursor = element;
    while (cursor && cursor.nodeType === 1 && cursor !== document.body && parts.length < 6) {
      const siblings = [...cursor.parentElement?.children || []].filter((candidate) => candidate.tagName === cursor.tagName);
      const suffix = siblings.length > 1 ? ":nth-of-type(" + (siblings.indexOf(cursor) + 1) + ")" : "";
      parts.unshift(cursor.tagName.toLowerCase() + suffix);
      cursor = cursor.parentElement;
    }
    return parts.join(" > ") || "body";
  };
  const nameOf = (element) => compact(element.getAttribute("aria-label")) || compact(element.id) || compact(element.className && typeof element.className === "string" ? element.className.split(/\\s+/)[0] : "") || element.tagName.toLowerCase();
  const asset = (url, hint) => {
    if (!url || url === "none" || url.startsWith("linear-gradient") || url.startsWith("radial-gradient")) return undefined;
    const existing = assets.get(url);
    if (existing) return existing.id;
    const id = "asset-" + (assets.size + 1);
    assets.set(url, { id, url, mimeType: hint });
    return id;
  };
  const backgroundUrl = (value) => {
    const match = /url\\(["']?(.+?)["']?\\)/.exec(value || "");
    return match ? match[1] : undefined;
  };
  const unsupported = (element, style) => {
    if (["CANVAS", "VIDEO", "IFRAME", "OBJECT", "EMBED"].includes(element.tagName)) return element.tagName.toLowerCase() + " cannot be converted to editable layers";
    if (style.filter && style.filter !== "none") return "CSS filter needs a raster fallback";
    if (style.backdropFilter && style.backdropFilter !== "none") return "backdrop-filter needs a raster fallback";
    if (style.maskImage && style.maskImage !== "none") return "CSS mask needs a raster fallback";
    if (style.mixBlendMode && style.mixBlendMode !== "normal") return "CSS blend mode needs a raster fallback";
    return undefined;
  };
  const paintOf = (style) => ({
    backgroundColor: style.backgroundColor,
    backgroundImage: style.backgroundImage,
    color: style.color,
    borderColor: style.borderTopColor,
    borderWidth: number(style.borderTopWidth),
    borderStyle: style.borderTopStyle,
    radius: [number(style.borderTopLeftRadius), number(style.borderTopRightRadius), number(style.borderBottomRightRadius), number(style.borderBottomLeftRadius)],
    opacity: number(style.opacity || "1"),
    boxShadow: style.boxShadow,
    overflow: ["hidden", "clip"].includes(style.overflow) ? style.overflow : "visible",
    transform: style.transform
  });
  const layoutOf = (style) => ({
    kind: style.display === "flex" || style.display === "inline-flex" ? "flex" : style.display === "grid" || style.display === "inline-grid" ? "grid" : "none",
    direction: style.flexDirection,
    wrap: style.flexWrap,
    justifyContent: style.justifyContent,
    alignItems: style.alignItems,
    rowGap: number(style.rowGap),
    columnGap: number(style.columnGap),
    padding: [number(style.paddingTop), number(style.paddingRight), number(style.paddingBottom), number(style.paddingLeft)],
    absolute: ["absolute", "fixed"].includes(style.position)
  });
  const textStyleOf = (style) => ({
    fontFamily: style.fontFamily,
    fontSize: number(style.fontSize),
    fontWeight: Number.parseInt(style.fontWeight, 10) || 400,
    fontStyle: style.fontStyle,
    lineHeight: style.lineHeight === "normal" ? number(style.fontSize) * 1.2 : number(style.lineHeight),
    letterSpacing: number(style.letterSpacing),
    textAlign: style.textAlign,
    textDecoration: style.textDecorationLine,
    textTransform: style.textTransform
  });
  const appendText = (parent, textNode, style) => {
    const text = compact(textNode.textContent);
    if (!text) return;
    const range = document.createRange();
    range.selectNodeContents(textNode);
    const rects = [...range.getClientRects()];
    if (!rects.length) return;
    const left = Math.min(...rects.map((item) => item.left));
    const top = Math.min(...rects.map((item) => item.top));
    const right = Math.max(...rects.map((item) => item.right));
    const bottom = Math.max(...rects.map((item) => item.bottom));
    const id = "node-" + (++sequence);
    nodes.push({ id, parentId: parent.id, children: [], kind: "text", name: text.slice(0, 80), source: parent.source + " ::text", rect: rectOf({ x: left, y: top, width: right - left, height: bottom - top }), zIndex: parent.zIndex + 0.01, paint: { color: style.color, opacity: number(style.opacity || "1") }, layout: { kind: "none" }, text, textStyle: textStyleOf(style) });
    parent.children.push(id);
  };
  const visit = (element, parentId) => {
    const style = getComputedStyle(element);
    const rect = element.getBoundingClientRect();
    if (!visible(element, style, rect)) return;
    const source = sourceOf(element);
    const reason = unsupported(element, style);
    const tag = element.tagName.toLowerCase();
    const id = "node-" + (++sequence);
    const directText = [...element.childNodes].some((child) => child.nodeType === Node.TEXT_NODE && compact(child.textContent));
    const childElements = [...element.children].filter((child) => { const childStyle = getComputedStyle(child); const childRect = child.getBoundingClientRect(); return visible(child, childStyle, childRect); });
    const imageUrl = tag === "img" ? element.currentSrc || element.src : backgroundUrl(style.backgroundImage);
    const imageAsset = asset(imageUrl, tag === "img" ? element.currentSrc?.split(".").pop() : undefined);
    const kind = reason ? "fallback" : tag === "img" ? "image" : tag === "svg" ? "svg" : directText && childElements.length === 0 ? "text" : (style.display === "flex" || style.display === "grid" || childElements.length > 0 ? "container" : "box");
    const scene = { id, parentId, children: [], kind, name: nameOf(element), source, rect: rectOf(rect), zIndex: Number.parseInt(style.zIndex, 10) || sequence, paint: paintOf(style), layout: layoutOf(style), assetId: imageAsset, fallbackReason: reason };
    if (kind === "text") { scene.text = compact(element.textContent); scene.textStyle = textStyleOf(style); }
    if (tag === "svg") { scene.assetId = asset("data:image/svg+xml," + encodeURIComponent(element.outerHTML), "image/svg+xml"); }
    nodes.push(scene);
    if (reason) {
      diagnostics.push({ severity: "warning", code: "UNSUPPORTED_SUBTREE", message: reason, viewportId: viewport.id, source });
      return id;
    }
    for (const child of element.childNodes) {
      if (child.nodeType === Node.TEXT_NODE && kind !== "text") appendText(scene, child, style);
      if (child.nodeType === Node.ELEMENT_NODE) visit(child, id);
    }
    for (const pseudo of ["::before", "::after"]) {
      const pseudoStyle = getComputedStyle(element, pseudo);
      const content = compact(pseudoStyle.content).replace(/^("|')|("|')$/g, "");
      if (content && content !== "none" && content !== "normal") {
        const pseudoId = "node-" + (++sequence);
        nodes.push({ id: pseudoId, parentId: id, children: [], kind: "text", name: pseudo, source: source + " " + pseudo, rect: rectOf(rect), zIndex: scene.zIndex + 0.02, paint: { color: pseudoStyle.color, opacity: number(pseudoStyle.opacity || "1") }, layout: { kind: "none", absolute: true }, text: content, textStyle: textStyleOf(pseudoStyle) });
        scene.children.push(pseudoId);
      }
    }
    return id;
  };
  const settle = async () => {
    try { await document.fonts?.ready; } catch (_) {}
    await Promise.all([...document.images].map((image) => image.decode?.().catch(() => undefined)));
    await new Promise((resolve) => requestAnimationFrame(() => requestAnimationFrame(resolve)));
    if (delay) await new Promise((resolve) => setTimeout(resolve, delay));
  };
  settle().then(() => {
    try {
      const root = document.body || document.documentElement;
      visit(root, undefined);
      const documentHeight = Math.max(document.documentElement.scrollHeight, document.body?.scrollHeight || 0, viewport.height);
      parent.postMessage({ type: "CAPTURE_RESULT", token, scene: { protocolVersion: ${PROTOCOL_VERSION}, viewport, documentSize: { width: Math.max(document.documentElement.scrollWidth, viewport.width), height: documentHeight }, nodes, assets: [...assets.values()], diagnostics } }, "*");
    } catch (error) {
      parent.postMessage({ type: "CAPTURE_ERROR", token, message: error instanceof Error ? error.message : String(error) }, "*");
    }
  });
})();`;
}
export const PROTOCOL_VERSION = 1 as const;

export type ScriptPolicy = "off" | "trusted";
export type Severity = "info" | "warning" | "error";
export type SceneKind = "container" | "box" | "text" | "image" | "svg" | "fallback";
export type LayoutKind = "none" | "flex" | "grid";

export interface ViewportSpec {
  id: string;
  name: string;
  width: number;
  height: number;
}

export const DEFAULT_VIEWPORTS: ViewportSpec[] = [
  { id: "desktop", name: "Desktop", width: 1440, height: 900 },
  { id: "tablet", name: "Tablet", width: 768, height: 1024 },
  { id: "mobile", name: "Mobile", width: 390, height: 844 }
];

export interface CaptureRequest {
  protocolVersion: typeof PROTOCOL_VERSION;
  html: string;
  baseUrl?: string;
  viewports: ViewportSpec[];
  scriptPolicy: ScriptPolicy;
  settleDelayMs: number;
}

export interface Rect {
  x: number;
  y: number;
  width: number;
  height: number;
}

export interface ScenePaint {
  backgroundColor?: string;
  backgroundImage?: string;
  color?: string;
  borderColor?: string;
  borderWidth?: number;
  borderStyle?: string;
  radius?: [number, number, number, number];
  opacity?: number;
  boxShadow?: string;
  overflow?: "visible" | "hidden" | "clip";
  transform?: string;
}

export interface TextStyle {
  fontFamily: string;
  fontSize: number;
  fontWeight: number;
  fontStyle: string;
  lineHeight: number;
  letterSpacing: number;
  textAlign: string;
  textDecoration: string;
  textTransform: string;
}

export interface SceneLayout {
  kind: LayoutKind;
  direction?: "row" | "row-reverse" | "column" | "column-reverse";
  wrap?: "wrap" | "nowrap";
  justifyContent?: string;
  alignItems?: string;
  rowGap?: number;
  columnGap?: number;
  padding?: [number, number, number, number];
  absolute?: boolean;
}

export interface AssetRef {
  id: string;
  url?: string;
  dataUrl?: string;
  mimeType?: string;
  width?: number;
  height?: number;
}

export interface SceneNode {
  id: string;
  parentId?: string;
  children: string[];
  kind: SceneKind;
  name: string;
  source: string;
  rect: Rect;
  zIndex: number;
  paint: ScenePaint;
  layout: SceneLayout;
  text?: string;
  textStyle?: TextStyle;
  assetId?: string;
  fallbackReason?: string;
}

export interface Diagnostic {
  severity: Severity;
  code: string;
  message: string;
  viewportId?: string;
  source?: string;
}

export interface SceneDocument {
  protocolVersion: typeof PROTOCOL_VERSION;
  viewport: ViewportSpec;
  documentSize: { width: number; height: number };
  nodes: SceneNode[];
  assets: AssetRef[];
  diagnostics: Diagnostic[];
}

export type UiToPluginMessage =
  | { type: "IMPORT"; protocolVersion: typeof PROTOCOL_VERSION; scenes: SceneDocument[] }
  | { type: "CANCEL"; protocolVersion: typeof PROTOCOL_VERSION };

export type PluginToUiMessage =
  | { type: "PROGRESS"; completed: number; total: number; label: string }
  | { type: "COMPLETE"; boards: number }
  | { type: "ERROR"; message: string };

