function applyGeometry(shape: Shape, node: SceneNode, parent: SceneNode | undefined, offset: { x: number; y: number }): void {
  const parentX = parent ? parent.rect.x : 0;
  const parentY = parent ? parent.rect.y : 0;
  shape.x = node.rect.x - parentX + offset.x;
  shape.y = node.rect.y - parentY + offset.y;
