    flex.wrap = layout.wrap || "nowrap";
    flex.rowGap = layout.rowGap || 0;
    flex.columnGap = layout.columnGap || 0;
    flex.topPadding = layout.padding?.[0] || 0;
    flex.rightPadding = layout.padding?.[1] || 0;
    flex.bottomPadding = layout.padding?.[2] || 0;
    flex.leftPadding = layout.padding?.[3] || 0;
    if (["start", "end", "center", "stretch"].includes(layout.alignItems || "")) flex.alignItems = layout.alignItems as typeof flex.alignItems;
    if (["start", "end", "center", "stretch", "space-between", "space-around", "space-evenly"].includes(layout.justifyContent || "")) flex.justifyContent = layout.justifyContent as typeof flex.justifyContent;
