          const child = nodes.get(childId);
          if (child) await render(child, shape, node);
        }
        completed += 1;
        if (completed % 25 === 0 || completed === total) {
          options.onProgress(completed, total, `Creating ${scene.viewport.name}`);
          await new Promise<void>((resolve) => setTimeout(resolve, 0));
        }
      };
      for (const root of roots) await render(root, board);
    }
    return boards;
  } catch (error) {
    for (const board of boards) board.remove();
    throw error;
  } finally {
    penpot.history.undoBlockFinish(undo);
