Interface Group
===============

Represents a group of shapes in Penpot.
This interface extends `ShapeBase` and includes properties and methods specific to groups.

```
interface Group {
    type: "group";
    children: Shape[];
    appendChild(child: Shape): void;
    insertChild(index: number, child: Shape): void;
    isMask(): boolean;
    makeMask(): void;
    removeMask(): void;
    getPluginData(key: string): string;
    setPluginData(key: string, value: string): void;
    getPluginDataKeys(): string[];
    getSharedPluginData(namespace: string, key: string): string;
    setSharedPluginData(namespace: string, key: string, value: string): void;
    getSharedPluginDataKeys(namespace: string): string[];
    id: string;
    name: string;
    parent: Shape | null;
    parentIndex: number;
    x: number;
    y: number;
    width: number;
    height: number;
    bounds: Bounds;
    center: Point;
    blocked: boolean;
    hidden: boolean;
    visible: boolean;
    proportionLock: boolean;
    constraintsHorizontal: "center" | "left" | "right" | "leftright" | "scale";
    constraintsVertical: "center" | "top" | "bottom" | "scale" | "topbottom";
    fixedWhenScrolling: boolean;
    borderRadius: number;
    borderRadiusTopLeft: number;
    borderRadiusTopRight: number;
    borderRadiusBottomRight: number;
    borderRadiusBottomLeft: number;
    opacity: number;
    blendMode:
        | "difference"
        | "normal"
        | "darken"
        | "multiply"
        | "color-burn"
        | "lighten"
        | "screen"
        | "color-dodge"
        | "overlay"
        | "soft-light"
        | "hard-light"
        | "exclusion"
        | "hue"
        | "saturation"
        | "color"
        | "luminosity";
    shadows: Shadow[];
    blur?: Blur;
    backgroundBlur?: Blur;
    exports: Export[];
    boardX: number;
    boardY: number;
    parentX: number;
    parentY: number;
    flipX: boolean;
    flipY: boolean;
    rotation: number;
    fills: Fill[]
    | "mixed";
    strokes: Stroke[];
    layoutChild?: LayoutChildProperties;
    layoutCell?: LayoutCellProperties;
    setParentIndex(index: number): void;
    tokens: {
        width: string;
        height: string;
        fill: string;
        x: string;
        y: string;
        all: string;
        borderRadiusTopLeft: string;
        borderRadiusTopRight: string;
        borderRadiusBottomRight: string;
        borderRadiusBottomLeft: string;
        shadow: string;
        strokeColor: string;
        strokeWidth: string;
        fontFamilies: string;
        fontSize: string;
        fontWeight: string;
        letterSpacing: string;
        rotation: string;
        opacity: string;
        layoutItemMinW: string;
        layoutItemMaxW: string;
        layoutItemMinH: string;
        layoutItemMaxH: string;
        rowGap: string;
        columnGap: string;
        paddingLeft: string;
        paddingTop: string;
        paddingRight: string;
        paddingBottom: string;
        marginLeft: string;
        marginTop: string;
        marginRight: string;
        marginBottom: string;
        textCase: string;
        textDecoration: string;
        typography: string;
    };
    isComponentInstance(): boolean;
    isComponentMainInstance(): boolean;
    isComponentCopyInstance(): boolean;
    isComponentRoot(): boolean;
    isComponentHead(): boolean;
    componentRefShape(): Shape | null;
    componentRoot(): Shape | null;
    componentHead(): Shape | null;
    component(): LibraryComponent | null;
    detach(): void;
    swapComponent(component: LibraryComponent): void;
    resetOverrides(): void;
    switchVariant(pos: number, value: string): void;
    combineAsVariants(ids: string[]): VariantContainer;
    isVariantHead(): boolean;
    resize(width: number, height: number): void;
    rotate(angle: number, center?: { x: number; y: number } | null): void;
    bringToFront(): void;
    bringForward(): void;
    sendToBack(): void;
    sendBackward(): void;
    export(config: Export): Promise<Uint8Array<ArrayBufferLike>>;
    interactions: Interaction[];
    addInteraction(
        trigger: Trigger,
        action: Action,
        delay?: number,
    ): Interaction;
    removeInteraction(interaction: Interaction): void;
    applyToken(token: Token, properties?: TokenProperty[]): void;
    clone(): Shape;
    remove(): void;
}
```

