export interface ResolvedSource {
  html: string;
  baseUrl?: string;
  sourceUrl?: string;
}

const FETCH_PROXY_PATH = "/__html_to_penpot/fetch";

function localFetchProxyUrl(target: string): string | undefined {
  const origin = typeof globalThis.location === "object" ? globalThis.location.origin : "";
  if (!origin || origin === "null") return undefined;
  return `${origin}${FETCH_PROXY_PATH}?url=${encodeURIComponent(target)}`;
}

/** Return a web URL only when the complete source value is a URL. */
export function sourceUrl(value: string): string | undefined {
  const trimmed = value.trim();
  if (!trimmed) return undefined;
  if (/\s/.test(trimmed)) return undefined;
  try {
    const parsed = new URL(trimmed);
    return parsed.protocol === "http:" || parsed.protocol === "https:" ? parsed.href : undefined;
  } catch {
    return undefined;
  }
}

/**
 * Resolve the editor value into HTML. Pasted markup is returned unchanged;
 * a complete HTTP(S) URL is fetched so the browser can render the page itself.
 * The direct request is attempted first. If the target does not grant browser
 * CORS, the local development server proxy is used instead.
 */
export async function resolveSource(value: string, explicitBaseUrl?: string): Promise<ResolvedSource> {
  const url = sourceUrl(value);
  if (!url) return { html: value, baseUrl: explicitBaseUrl || undefined };

  let response: Response | undefined;
  let directError: unknown;
  try {
    response = await fetch(url, { credentials: "omit", redirect: "follow" });
  } catch (error) {
    directError = error;
  }

  if (!response) {
    const proxyUrl = localFetchProxyUrl(url);
    if (proxyUrl) {
      try {
        response = await fetch(proxyUrl, { credentials: "omit", redirect: "follow" });
      } catch (proxyError) {
        const directDetail = directError instanceof Error ? directError.message : "the browser blocked the request";
        const proxyDetail = proxyError instanceof Error ? proxyError.message : "the local proxy could not be reached";
        throw new Error(`Unable to load ${url}. Direct loading was blocked by CORS (${directDetail}); the local fetch proxy also failed (${proxyDetail}). Paste the page HTML instead.`);
      }
    } else {
      const detail = directError instanceof Error ? directError.message : "the browser blocked the request";
      throw new Error(`Unable to load ${url}. Paste the page HTML instead; direct URL loading requires browser CORS (${detail}).`);
    }
  }
  if (!response.ok) throw new Error(`Unable to load ${url}: the server returned HTTP ${response.status}.`);
  const html = await response.text();
  if (!html.trim()) throw new Error(`Unable to load ${url}: the response did not contain HTML.`);

  return {
    html,
    baseUrl: explicitBaseUrl || response.headers.get("X-HTML-Source-URL") || url,
    sourceUrl: url
  };
}
import { buildExtractorScript } from "./extractor";
import type { ScriptPolicy, ViewportSpec } from "../shared/contracts";

export function isSafeBaseUrl(value: string | undefined): value is string {
  if (!value) return false;
  try {
    const url = new URL(value);
    return url.protocol === "https:" || url.protocol === "http:";
  } catch {
    return false;
  }
}

export function prepareSandboxDocument(input: {
  html: string;
  baseUrl?: string;
  scriptPolicy: ScriptPolicy;
  token: string;
  viewport: ViewportSpec;
  settleDelayMs: number;
}): string {
  const parser = new DOMParser();
  const document = parser.parseFromString(input.html, "text/html");
  const nonce = crypto.randomUUID();
  const head = document.head || document.documentElement.insertBefore(document.createElement("head"), document.body);

  document.querySelectorAll("base").forEach((base) => base.remove());
  if (isSafeBaseUrl(input.baseUrl)) {
    const base = document.createElement("base");
    base.href = input.baseUrl;
    head.prepend(base);
  }

  document.querySelectorAll("script").forEach((script) => {
    if (input.scriptPolicy === "off") script.remove();
    else script.setAttribute("nonce", nonce);
  });

  const policy = input.scriptPolicy === "trusted"
    ? `default-src 'none'; img-src data: blob: http: https:; style-src 'unsafe-inline' http: https:; font-src data: http: https:; script-src 'nonce-${nonce}' http: https:; connect-src http: https:; media-src data: blob: http: https:; object-src 'none'; frame-src 'none'; form-action 'none'; base-uri 'self' http: https:`
    : `default-src 'none'; img-src data: blob: http: https:; style-src 'unsafe-inline' http: https:; font-src data: http: https:; script-src 'nonce-${nonce}'; media-src data: blob: http: https:; object-src 'none'; frame-src 'none'; form-action 'none'; base-uri 'self' http: https:`;
  const csp = document.createElement("meta");
  csp.httpEquiv = "Content-Security-Policy";
  csp.content = policy;
  head.prepend(csp);
  const referrer = document.createElement("meta");
  referrer.name = "referrer";
  referrer.content = "no-referrer";
  head.prepend(referrer);
  const freeze = document.createElement("style");
  freeze.textContent = "*,*::before,*::after{animation:none!important;transition:none!important;caret-color:transparent!important}";
  head.append(freeze);
  const extractor = document.createElement("script");
  extractor.setAttribute("nonce", nonce);
  extractor.textContent = buildExtractorScript(input.token, input.viewport, input.settleDelayMs);
  document.body.append(extractor);
  return "<!doctype html>\n" + document.documentElement.outerHTML;
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

const FETCH_PROXY_PATH = "/__html_to_penpot/fetch";
const MAX_HTML_BYTES = 10 * 1024 * 1024;
const FETCH_TIMEOUT_MS = 15_000;

function htmlFetchProxy() {
  return {
    name: "html-to-penpot-fetch-proxy",
    configurePreviewServer(server: { middlewares: { use: (handler: (request: any, response: any, next: () => void) => void) => void } }) {
      server.middlewares.use(async (request, response, next) => {
        if (request.url === undefined || !request.url.startsWith(FETCH_PROXY_PATH)) {
          next();
          return;
        }

        if (request.method === "OPTIONS") {
          response.statusCode = 204;
          response.setHeader("Access-Control-Allow-Origin", "*");
          response.setHeader("Access-Control-Allow-Methods", "GET, OPTIONS");
          response.end();
          return;
        }
        if (request.method !== "GET") {
          response.statusCode = 405;
          response.end("Only GET is supported.");
          return;
        }

        const target = new URL(request.url, "http://localhost").searchParams.get("url");
        if (!target) {
          response.statusCode = 400;
          response.end("Missing url query parameter.");
          return;
        }

        let targetUrl: URL;
        try {
          targetUrl = new URL(target);
          if (targetUrl.protocol !== "http:" && targetUrl.protocol !== "https:") throw new Error("unsupported protocol");
        } catch {
          response.statusCode = 400;
          response.end("The url must be an http(s) URL.");
          return;
        }

        try {
          const upstream = await fetch(targetUrl, {
            headers: { Accept: "text/html,application/xhtml+xml;q=0.9,*/*;q=0.1" },
            redirect: "follow",
            signal: AbortSignal.timeout(FETCH_TIMEOUT_MS)
          });
          if (!upstream.ok) {
            response.statusCode = upstream.status >= 400 && upstream.status < 500 ? upstream.status : 502;
            response.setHeader("Access-Control-Allow-Origin", "*");
            response.end(`The target server returned HTTP ${upstream.status}.`);
            return;
          }

          const html = await upstream.text();
          if (Buffer.byteLength(html, "utf8") > MAX_HTML_BYTES) {
            response.statusCode = 413;
            response.setHeader("Access-Control-Allow-Origin", "*");
            response.end("The target page is larger than the 10 MB limit.");
            return;
          }

          response.statusCode = 200;
          response.setHeader("Access-Control-Allow-Origin", "*");
          response.setHeader("Access-Control-Expose-Headers", "X-HTML-Source-URL");
          response.setHeader("Content-Type", "text/html; charset=utf-8");
          response.setHeader("Cache-Control", "no-store");
          response.setHeader("X-HTML-Source-URL", upstream.url || targetUrl.href);
          response.end(html);
        } catch (error) {
          response.statusCode = 502;
          response.setHeader("Access-Control-Allow-Origin", "*");
          const detail = error instanceof Error ? error.message : "the proxy request failed";
          response.end(`Unable to fetch the target page: ${detail}`);
        }
      });
    }
  };
}

