import { useEffect, useMemo, useState } from "react";
import { capturePage } from "./capture/sandbox";
import { isSafeBaseUrl } from "./capture/prepareDocument";
import { resolveSource } from "./capture/source";
import { DEFAULT_VIEWPORTS, PROTOCOL_VERSION, type CaptureRequest, type PluginToUiMessage, type SceneDocument, type ScriptPolicy, type ViewportSpec } from "./shared/contracts";
import { sceneWarnings } from "./shared/validation";

type Phase = "idle" | "capturing" | "ready" | "importing" | "complete" | "error";

function postToPlugin(message: unknown) {
  window.parent.postMessage(message, "*");
}

function viewportLabel(viewport: ViewportSpec) {
  return `${viewport.name} · ${viewport.width}×${viewport.height}`;
}

export default function App() {
  const [source, setSource] = useState("");
  const [baseUrl, setBaseUrl] = useState("");
  const [viewports, setViewports] = useState<ViewportSpec[]>(DEFAULT_VIEWPORTS);
  const [scriptPolicy, setScriptPolicy] = useState<ScriptPolicy>("off");
  const [settleDelayMs, setSettleDelayMs] = useState(300);
  const [scenes, setScenes] = useState<SceneDocument[]>([]);
  const [phase, setPhase] = useState<Phase>("idle");
  const [progress, setProgress] = useState("");
  const [error, setError] = useState<string>();
  const [advanced, setAdvanced] = useState(false);

  useEffect(() => {
    const receive = (event: MessageEvent<PluginToUiMessage>) => {
      const message = event.data;
      if (!message || typeof message !== "object" || !("type" in message)) return;
      if (message.type === "PROGRESS") setProgress(`${message.label}: ${message.completed}/${message.total}`);
      if (message.type === "COMPLETE") {
        setPhase("complete");
        setProgress(`Imported ${message.boards} editable board${message.boards === 1 ? "" : "s"}.`);
      }
      if (message.type === "ERROR") {
        setPhase("error");
        setError(message.message);
      }
    };
    window.addEventListener("message", receive);
    return () => window.removeEventListener("message", receive);
  }, []);

  const warnings = useMemo(() => sceneWarnings(scenes), [scenes]);
  const diagnostics = useMemo(() => scenes.flatMap((scene) => scene.diagnostics), [scenes]);
  const resetCapture = () => {
    setScenes([]);
    if (phase !== "importing") setPhase("idle");
  };

  const analyze = async () => {
    if (!source.trim()) {
      setPhase("error");
      setError("Paste the HTML for one page before analyzing it.");
      return;
    }
    if (baseUrl && !isSafeBaseUrl(baseUrl)) {
      setPhase("error");
      setError("The base URL must use http:// or https://.");
      return;
    }
    if (scriptPolicy === "trusted" && !window.confirm("Only enable scripts for source you trust. A sandbox prevents access to Penpot, but a broken or hostile script can still hang this plugin tab. Continue?")) return;
    setError(undefined);
    setScenes([]);
    setPhase("capturing");
    setProgress("Preparing page…");
    try {
      const resolved = await resolveSource(source, baseUrl || undefined);
      const request: CaptureRequest = { protocolVersion: PROTOCOL_VERSION, html: resolved.html, baseUrl: resolved.baseUrl, viewports, scriptPolicy, settleDelayMs };
      const captured = await capturePage(request, (completed, total) => setProgress(`Rendered ${completed}/${total} viewport${total === 1 ? "" : "s"}.`));
      setScenes(captured);
      setPhase("ready");
      setProgress(`Analyzed ${captured.length} viewport${captured.length === 1 ? "" : "s"}.`);
    } catch (captureError) {
      setPhase("error");
      setError(captureError instanceof Error ? captureError.message : "Unable to render the supplied page.");
    }
  };

  const importScenes = () => {
    if (!scenes.length) return;
    if ((warnings.needsLayerConfirmation || warnings.tallViewports.length) && !window.confirm(`This import contains ${warnings.layers.toLocaleString()} layers${warnings.tallViewports.length ? ` and tall boards (${warnings.tallViewports.join(", ")})` : ""}. It may be slow. Import anyway?`)) return;
    setPhase("importing");
    setError(undefined);
    setProgress("Preparing Penpot layers…");
    postToPlugin({ type: "IMPORT", protocolVersion: PROTOCOL_VERSION, scenes });
  };

  const cancel = () => {
    postToPlugin({ type: "CANCEL", protocolVersion: PROTOCOL_VERSION });
    setProgress("Cancelling after the current layer…");
  };

  const updateViewport = (id: string, field: keyof ViewportSpec, value: string) => {
    setViewports((current) => current.map((viewport) => viewport.id !== id ? viewport : field === "name" || field === "id" ? { ...viewport, [field]: value } : { ...viewport, [field]: Math.max(1, Number(value) || 1) }));
    resetCapture();
  };

  return <main className="app-shell">
    <header>
      <div>
        <h1>Ultimate HTML to Penpot</h1>
        <p>Turn one rendered HTML page into editable boards.</p>
      </div>
      <span className={`status status-${phase}`}>{phase === "ready" ? "Ready" : phase === "importing" ? "Importing" : phase === "capturing" ? "Analyzing" : phase === "complete" ? "Done" : "Draft"}</span>
    </header>

    <section className="source-section" aria-label="Page source">
      <label htmlFor="base-url">Base URL <span>optional — resolves relative assets when pasting HTML</span></label>
      <input id="base-url" value={baseUrl} placeholder="https://example.com/page/" onChange={(event) => { setBaseUrl(event.target.value); resetCapture(); }} />
      <label htmlFor="html-source">Page source <span>paste complete HTML or enter a full HTTP(S) URL</span></label>
      <textarea id="html-source" className="editor" value={source} spellCheck={false} aria-label="HTML source" placeholder="<!doctype html>\n<html>…</html>\n\n—or—\n\nhttps://example.com/page" onChange={(event) => { setSource(event.target.value); resetCapture(); }} />
    </section>

    <section className="viewport-section">
      <div className="section-heading"><h2>Responsive boards</h2><button className="text-button" onClick={() => { setViewports([...viewports, { id: crypto.randomUUID(), name: "Custom", width: 1024, height: 800 }]); resetCapture(); }}>Add viewport</button></div>
      <div className="viewport-list">
        {viewports.map((viewport) => <div className="viewport-row" key={viewport.id}>
          <input aria-label={`${viewport.name} name`} value={viewport.name} onChange={(event) => updateViewport(viewport.id, "name", event.target.value)} />
          <input aria-label={`${viewport.name} width`} type="number" min="1" value={viewport.width} onChange={(event) => updateViewport(viewport.id, "width", event.target.value)} />
          <span>×</span>
          <input aria-label={`${viewport.name} height`} type="number" min="1" value={viewport.height} onChange={(event) => updateViewport(viewport.id, "height", event.target.value)} />
          <button aria-label={`Remove ${viewport.name}`} className="icon-button" disabled={viewports.length === 1} onClick={() => { setViewports(viewports.filter((item) => item.id !== viewport.id)); resetCapture(); }}>×</button>
        </div>)}
      </div>
    </section>

    <section className="advanced-section">
      <button className="advanced-toggle" onClick={() => setAdvanced(!advanced)} aria-expanded={advanced}>Advanced capture {advanced ? "−" : "+"}</button>
      {advanced && <div className="advanced-panel">
        <label className="checkbox"><input type="checkbox" checked={scriptPolicy === "trusted"} onChange={(event) => { setScriptPolicy(event.target.checked ? "trusted" : "off"); resetCapture(); }} /> Run trusted page scripts <span>Off by default. Never use for untrusted HTML.</span></label>
        <label>Additional settle delay <output>{settleDelayMs}ms</output><input type="range" min="0" max="5000" step="100" value={settleDelayMs} onChange={(event) => { setSettleDelayMs(Number(event.target.value)); resetCapture(); }} /></label>
      </div>}
    </section>

    {scenes.length > 0 && <section className="analysis" aria-live="polite">
      <h2>Analysis</h2>
      <div className="summary"><strong>{warnings.layers.toLocaleString()}</strong> editable layers across {scenes.length} boards · {diagnostics.length} diagnostics</div>
      <ul>
        {scenes.map((scene) => <li key={scene.viewport.id}>{viewportLabel(scene.viewport)} — {scene.documentSize.width}×{Math.round(scene.documentSize.height)}px, {scene.nodes.length} layers</li>)}
        {diagnostics.slice(0, 4).map((diagnostic, index) => <li className="warning" key={`${diagnostic.code}-${index}`}>{diagnostic.message} {diagnostic.source ? `(${diagnostic.source})` : ""}</li>)}
        {diagnostics.length > 4 && <li className="warning">+ {diagnostics.length - 4} more diagnostics</li>}
      </ul>
    </section>}

    {error && <p className="error" role="alert">{error}</p>}
    {(phase === "capturing" || phase === "importing" || phase === "complete" || phase === "ready") && <p className="progress" aria-live="polite">{progress}</p>}
    <footer>
      {phase === "importing" ? <button className="secondary" onClick={cancel}>Cancel import</button> : <button className="secondary" onClick={analyze} disabled={phase === "capturing"}>Analyze page</button>}
      <button className="primary" onClick={importScenes} disabled={phase !== "ready"}>Import to Penpot</button>
    </footer>
  </main>;
}
import { importScenes, ImportCancelledError } from "./importer/penpot";
import { PROTOCOL_VERSION, type PluginToUiMessage, type UiToPluginMessage } from "./shared/contracts";
import { validateScenes } from "./shared/validation";

let cancelled = false;

function send(message: PluginToUiMessage) {
  penpot.ui.sendMessage(message);
}

penpot.ui.open("Ultimate HTML to Penpot", `?theme=${penpot.theme}`, { width: 620, height: 760 });

penpot.ui.onMessage<UiToPluginMessage>(async (message) => {
  if (!message || message.protocolVersion !== PROTOCOL_VERSION) return;
  if (message.type === "CANCEL") {
    cancelled = true;
    return;
  }
  if (message.type !== "IMPORT") return;
  cancelled = false;
  try {
    const scenes = validateScenes(message.scenes);
    const boards = await importScenes(scenes, {
      isCancelled: () => cancelled,
      onProgress: (completed, total, label) => send({ type: "PROGRESS", completed, total, label })
    });
    send({ type: "COMPLETE", boards: boards.length });
  } catch (error) {
    send({ type: "ERROR", message: error instanceof ImportCancelledError ? "Import cancelled; partial boards were removed." : error instanceof Error ? error.message : "Import failed." });
  }
});
import type { Board, Fill, Gradient, Shape, Text } from "@penpot/plugin-types";
import type { AssetRef, SceneDocument, SceneNode, ScenePaint } from "../shared/contracts";

export class ImportCancelledError extends Error {
  constructor() { super("Import cancelled."); }
}

export interface ImportOptions {
  isCancelled: () => boolean;
  onProgress: (completed: number, total: number, label: string) => void;
}

const IMPORT_NAMESPACE = "ultimate-html-to-penpot";

function cssColor(value: string | undefined): string | undefined {
  if (!value || value === "transparent" || value === "rgba(0, 0, 0, 0)") return undefined;
  if (value.startsWith("#")) return value;
  const match = value.match(/^rgba?\((\d+),\s*(\d+),\s*(\d+)/i);
  if (!match) return undefined;
  return `#${match.slice(1).map((part) => Number(part).toString(16).padStart(2, "0")).join("")}`;
}

function cssGradient(value: string | undefined): Gradient | undefined {
  if (!value || (!value.startsWith("linear-gradient") && !value.startsWith("radial-gradient"))) return undefined;
  const colors = (value.match(/(?:rgba?\([^)]*\)|#[\da-f]{3,8})/gi) || []).map(cssColor).filter((color): color is string => Boolean(color));
  if (colors.length < 2) return undefined;
  const stops = colors.map((color, index) => ({ color, offset: index / (colors.length - 1), opacity: 1 }));
  if (value.startsWith("radial-gradient")) return { type: "radial", startX: 0.5, startY: 0.5, endX: 1, endY: 0.5, width: 0.5, stops };
  const angle = value.match(/(-?\d+(?:\.\d+)?)deg/);
  const degrees = angle ? Number(angle[1]) : 180;
  const radians = (degrees - 90) * Math.PI / 180;
  return { type: "linear", startX: 0.5 - Math.cos(radians) / 2, startY: 0.5 - Math.sin(radians) / 2, endX: 0.5 + Math.cos(radians) / 2, endY: 0.5 + Math.sin(radians) / 2, width: 1, stops };
}

function applyShadow(shape: Shape, value: string | undefined): void {
  if (!value || value === "none") return;
  const color = cssColor((value.match(/rgba?\([^)]*\)|#[\da-f]{3,8}/i) || [])[0]);
  const dimensions = (value.match(/-?\d+(?:\.\d+)?px/g) || []).map((dimension) => Number.parseFloat(dimension));
  if (!color || dimensions.length < 3) return;
  shape.shadows = [{ style: value.includes("inset") ? "inner-shadow" : "drop-shadow", offsetX: dimensions[0], offsetY: dimensions[1], blur: dimensions[2], spread: dimensions[3] || 0, color: { color } }];
}

function applyPaint(shape: Shape, paint: ScenePaint): void {
  const color = cssColor(paint.backgroundColor);
  const gradient = cssGradient(paint.backgroundImage);
  const fills: Fill[] = gradient ? [{ fillColorGradient: gradient }] : color ? [{ fillColor: color, fillOpacity: paint.opacity ?? 1 }] : [];
  if ("fills" in shape && shape.type !== "group") (shape as Shape & { fills: Fill[] }).fills = fills;
  shape.opacity = paint.opacity ?? 1;
  if (paint.radius) {
    [shape.borderRadiusTopLeft, shape.borderRadiusTopRight, shape.borderRadiusBottomRight, shape.borderRadiusBottomLeft] = paint.radius;
  }
  const stroke = cssColor(paint.borderColor);
  if (stroke && paint.borderWidth && paint.borderStyle !== "none") {
    shape.strokes = [{ strokeColor: stroke, strokeWidth: paint.borderWidth, strokeStyle: "solid", strokeAlignment: "center" }];
  }
  applyShadow(shape, paint.boxShadow);
  const matrix = paint.transform?.match(/^matrix\(([^)]+)\)$/);
  if (matrix) {
    const values = matrix[1].split(",").map(Number);
    if (values.length >= 2) shape.rotation = Math.atan2(values[1], values[0]) * 180 / Math.PI;
  }
  if (paint.overflow === "hidden" || paint.overflow === "clip") {
    if (shape.type === "board") (shape as Board).clipContent = true;
  }
}

function applyGeometry(shape: Shape, node: SceneNode, pageOrigin: { x: number; y: number }): void {
  // Penpot stores a nested shape's coordinates in page space. Set these only
  // after parentage is established; setting local DOM coordinates beforehand
  // puts children outside their clipping board.
  shape.x = pageOrigin.x + node.rect.x;
  shape.y = pageOrigin.y + node.rect.y;
  shape.resize(Math.max(0.1, node.rect.width), Math.max(0.1, node.rect.height));
}

function textAlign(value: string): Text["align"] {
  return ["left", "right", "center", "justify"].includes(value) ? value as Text["align"] : "left";
}

const GENERIC_FONT_FAMILIES = new Set([
  "caption",
  "icon",
  "menu",
  "message-box",
  "small-caption",
  "status-bar",
  "-apple-system",
  "blinkmacsystemfont",
  "system-ui",
  "ui-sans-serif",
  "ui-serif",
  "ui-monospace",
  "ui-rounded",
  "sans-serif",
  "serif",
  "monospace",
  "cursive",
  "fantasy",
  "math"
]);

function penpotFontFamily(value: string | undefined): string {
  const family = value?.split(",")[0].replace(/["']/g, "").trim() || "Inter";
  return GENERIC_FONT_FAMILIES.has(family.toLowerCase()) ? "Inter" : family;
}

function penpotFontCandidates(value: string | undefined): string[] {
  const family = penpotFontFamily(value);
  if (family === "Inter") return [family];
  // Some webfont CSS declares the PostScript face name as the family, for
  // example `Poppins-Regular`. Penpot usually registers the family as
  // `Poppins`, so try that normalized name before falling back.
  const normalized = family.replace(/(?:[-_](?:regular|normal|italic|oblique|thin|extralight|light|medium|semibold|bold|extrabold|black)|[-_]\d{3})$/i, "");
  return normalized && normalized !== family ? [family, normalized, "Inter"] : [family, "Inter"];
}

function applyPenpotFontFamily(text: Text, value: string | undefined): void {
  for (const family of penpotFontCandidates(value)) {
    try {
      text.fontFamily = family;
      return;
    } catch {
      // Browser fonts are not necessarily installed in Penpot. Try the
      // normalized family and finally the guaranteed Inter fallback.
    }
  }
}

function createText(node: SceneNode): Text {
  const text = penpot.createText(node.text || "");
  if (!text) throw new Error(`Unable to create text layer: ${node.name}`);
  const style = node.textStyle;
  text.growType = "fixed";
  // CSS lays inline content out from the top of its line box. Make that
  // explicit because a Penpot text layer's editor default can be center.
  text.verticalAlign = "top";
  text.direction = "ltr";
  text.characters = node.text || "";
  if (style) {
    // CSS generic families (for example `system-ui`) are valid in a browser
    // but rejected by Penpot's fontFamily validator. Inter is Penpot's
    // guaranteed fallback and keeps the layer editable instead of aborting
    // the entire import.
    applyPenpotFontFamily(text, style.fontFamily);
    // Penpot's plugin API expects numeric string values, not CSS units.
    text.fontSize = String(Math.max(1, style.fontSize));
    text.fontWeight = String(style.fontWeight);
    text.fontStyle = style.fontStyle === "italic" ? "italic" : "normal";
    // Scene text styles use Penpot's unitless line-height multiplier.
    text.lineHeight = String(Math.max(0.01, style.lineHeight));
    // CSS permits negative tracking; Penpot's text API currently does not.
    text.letterSpacing = String(Math.max(0, style.letterSpacing));
    text.align = textAlign(style.textAlign);
    const textTransform = ["uppercase", "lowercase", "capitalize"].find((value) => value === style.textTransform);
    if (textTransform) text.textTransform = textTransform as Text["textTransform"];
    if (style.textDecoration.includes("line-through")) text.textDecoration = "line-through";
    else if (style.textDecoration.includes("underline")) text.textDecoration = "underline";
  }
  const color = cssColor(node.paint.color);
  if (color) text.fills = [{ fillColor: color, fillOpacity: node.paint.opacity ?? 1 }];
  return text;
}

async function mediaFor(asset: AssetRef) {
  if (asset.url?.startsWith("data:")) {
    const response = await fetch(asset.url);
    const data = new Uint8Array(await response.arrayBuffer());
    return penpot.uploadMediaData(asset.id, data, response.headers.get("content-type") || asset.mimeType || "image/png");
  }
  if (asset.url) return penpot.uploadMediaUrl(asset.id, asset.url);
  return undefined;
}

function svgTextOf(asset: AssetRef | undefined): string | undefined {
  const url = asset?.url;
  if (!url || !url.toLowerCase().startsWith("data:image/svg+xml")) return undefined;
  const comma = url.indexOf(",");
  if (comma < 0) return undefined;
  const encoded = url.slice(comma + 1);
  if (url.slice(0, comma).toLowerCase().endsWith(";base64")) {
    try { return atob(encoded); } catch { return undefined; }
  }
  try { return decodeURIComponent(encoded); } catch { return undefined; }
}

function needsContainerBackdrop(node: SceneNode): boolean {
  const paint = node.paint;
  return Boolean(
    cssColor(paint.backgroundColor) ||
    (paint.backgroundImage && paint.backgroundImage !== "none") ||
    (paint.borderWidth && paint.borderWidth > 0 && paint.borderStyle !== "none") ||
    (paint.boxShadow && paint.boxShadow !== "none") ||
    paint.radius?.some((radius) => radius > 0) ||
    paint.overflow === "hidden" ||
    paint.overflow === "clip"
  );
}

function createContainerBackdrop(node: SceneNode): Shape {
  const backdrop = penpot.createRectangle();
  // Opacity belongs to the complete container compositing group. Keeping
  // the backdrop fully opaque lets the group apply it once to both the
  // background and editable descendants.
  applyPaint(backdrop, { ...node.paint, opacity: 1 });
  return backdrop;
}

function applyContainerOpacity(shape: Shape, node: SceneNode): void {
  const opacity = node.paint.opacity;
  if (opacity === undefined || opacity === 1) return;
  shape.opacity = (shape.opacity ?? 1) * opacity;
}

function metadata(shape: Shape, node: SceneNode, viewportId: string): void {
  shape.name = node.name.slice(0, 200);
  shape.setPluginData("importer", IMPORT_NAMESPACE);
  shape.setPluginData("viewport", viewportId);
  shape.setPluginData("source", node.source);
