const r = await tools.exec_command({cmd:"python3 - <<'PY'
import json
j=json.load(open('/tmp/network.json'))
for req in j['result']['requests']:
 if req.get('status')!=200 or 'update-file' not in req['url'] or not req.get('postData'): continue
 try:d=json.loads(req['postData'])
 except:continue
 def has(v):
  if isinstance(v,dict): return ('~:text' in v and isinstance(v['~:text'],str) and 'Pine Island Food Pantry was founded' in v['~:text']) or any(has(x) for x in v.values())
  if isinstance(v,list): return any(has(x) for x in v)
  return False
 ids=[]
 def walk(v):
  if isinstance(v,dict):
   if '~#shape' in v and has(v['~#shape']): ids.append(v['~#shape'].get('~:id'))
   for x in v.values():walk(x)
  elif isinstance(v,list):
   for x in v:walk(x)
 walk(d)
 ids=set(ids)
 if not ids:continue
 print('\nREQ',req['requestId'],'ids',ids)
 for ch in d.get('~:changes',[]):
  cid=ch.get('~:id')
  if cid not in ids:continue
  print('change',ch.get('~:type'),cid)
  for op in ch.get('~:operations',[]):
   attr=op.get('~:attr')
   if attr in ['~:grow-type','~:width','~:height','~:x','~:y','~:content']:
    val=op.get('~:val')
    print(attr, val if attr!='~:content' else ('text=' + str(val)[:160]))
